from pathlib import Path
import pandas as pd, geopandas as gpd, matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
plt.rcParams['font.family']='Malgun Gothic'; plt.rcParams['axes.unicode_minus']=False
R=Path(__file__).resolve().parents[2]; O=Path(__file__).resolve().parent; O.mkdir(exist_ok=True)
pop=pd.read_csv(R/'visualizations/09_population_province_map/dong_age_population.csv'); poly=gpd.read_file(R/'N3A_G0110000.shp',encoding='euc-kr'); poly['시도코드']=poly.BJCD.astype(str).str[:2]; names={'11':'서울특별시','26':'부산광역시','27':'대구광역시','28':'인천광역시','29':'광주광역시','30':'대전광역시','31':'울산광역시','36':'세종특별자치시','41':'경기도','51':'강원특별자치도','43':'충청북도','44':'충청남도','52':'전북특별자치도','46':'전라남도','47':'경상북도','48':'경상남도','50':'제주특별자치도'}; poly['시도']=poly['시도코드'].map(names); poly['읍면동']=poly.NAME.str.strip(); poly=poly.merge(pop,on=['시도','읍면동'],how='inner')
st=pd.read_csv(R/'visualizations/07_bus_stops_2025/bus_stops.csv'); pts=gpd.GeoDataFrame(st,geometry=gpd.points_from_xy(st.stop_lon,st.stop_lat),crs=4326).to_crs(poly.crs); join=gpd.sjoin(pts,poly[['시도','읍면동','geometry']],predicate='within',how='left'); counts=join.groupby(['시도','읍면동']).size().rename('정류장수').reset_index(); m=poly.merge(counts,on=['시도','읍면동'],how='left'); m['정류장수']=m['정류장수'].fillna(0).astype(int); m['정류장_1만명']=m['정류장수']/m['합계']*10000; m[['시도','읍면동','합계','정류장수','정류장_1만명']].to_csv(O/'stop_supply_by_dong.csv',index=False,encoding='utf-8-sig')
fig,ax=plt.subplots(figsize=(12,10),facecolor='#f8fafc'); q=m['정류장_1만명'].quantile([.02,.98]); m.plot(column='정류장_1만명',ax=ax,cmap='YlGnBu',vmin=q.iloc[0],vmax=q.iloc[1],edgecolor='white',linewidth=.05,legend=True,legend_kwds={'label':'인구 1만 명당 버스 정류장 수','shrink':.7}); ax.set_axis_off(); fig.text(.07,.95,'인구 대비 버스 정류장 공급 격차',fontsize=22,weight='bold',color='#172b4d'); fig.text(.07,.91,'색이 진할수록 인구 1만 명당 정류장이 많음 · 2025년 3월 GTFS',fontsize=11,color='#475569'); fig.text(.07,.035,f'연결 읍면동 {len(m):,}개 · 정류장 공간조인 미매칭 {join.시도.isna().sum():,}개\n상·하위 2%를 색상 범위에서 제외했으며 원자료 집계는 CSV에 보존했습니다.',fontsize=9,color='#475569'); fig.subplots_adjust(top=.86,bottom=.1,left=.03,right=.97); fig.savefig(O/'stop_supply_map.png',dpi=240); plt.close(fig)
low=m.sort_values('정류장_1만명').head(10); high=m.sort_values('정류장_1만명',ascending=False).head(10); insight=f'''# 10번 시각화: 인구 대비 버스 정류장 공급\n\n![지도](stop_supply_map.png)\n\n인구 1만 명당 정류장 수를 계산했습니다. `정류장수 ÷ 총인구 × 10,000`이며, 값이 낮을수록 인구 대비 정류장 공급이 적습니다. 정류장 좌표를 읍면동 폴리곤에 공간조인한 뒤 총인구와 결합했습니다.\n\n이 지표만으로 서비스 품질이나 이용 가능성을 확정할 수는 없습니다. 정류장 위치는 표시하지만 배차 간격·노선 수·승하차 수요·보행거리·지형은 반영하지 않았습니다. 따라서 값이 낮은 지역은 DRT·마을버스 후보를 찾는 1차 선별 지표로 사용하고, 이후 노선·운행회차와 함께 검토해야 합니다.\n\n## 전처리\n- 2025년 3월 버스 route_type 0·3·5에 연결된 정류장 {len(st):,}개를 사용했습니다.\n- 읍면동 경계와 좌표계를 맞춘 뒤 `within` 공간조인으로 정류장을 배정했습니다. 미매칭은 {join.시도.isna().sum():,}개입니다.\n- 인구 자료의 총인구와 결합했고, 정류장이 없는 읍면동도 0개로 유지했습니다.\n- 색상만 2~98 백분위 범위로 조정했습니다.\n\n## 해석\n- 인구가 많은데 정류장 수가 적은 지역은 공급 부족 후보입니다.\n- 인구는 적지만 정류장이 많은 지역은 생활권이 넓거나 마을버스 성격의 공급일 수 있어, 단순히 과잉 공급으로 판단하면 안 됩니다.\n- 다음 단계에서는 고령화율, 인구 대비 정류장 수, 정류장별 노선·운행횟수를 결합해 이동격차 지수를 만들 수 있습니다.\n\n하위 10개와 상위 10개 목록은 `stop_supply_by_dong.csv`에서 확인할 수 있습니다.\n'''; (O/'README.md').write_text(insight,encoding='utf-8')
